"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["94190"],{30182(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.fato_coletado.obrigatoriedade_invalida","status":422,"titulo":"Obrigatoriedade do campo inv\xe1lida"},"descricao":{"codigo":"uniplus.selecao.fato_coletado.obrigatoriedade_invalida","requisitos":[],"oQueAconteceu":["Cada item de um formul\xe1rio, cada grupo de campos e cada campo dentro de um grupo\\ndeclara se \xe9 obrigat\xf3rio. A declara\xe7\xe3o s\xf3 tem tr\xeas formas v\xe1lidas:","- `SEMPRE`, sem condi\xe7\xe3o: o candidato sempre responde;\\n- `NUNCA`, sem condi\xe7\xe3o: o campo \xe9 opcional;\\n- `QUANDO`, com a condi\xe7\xe3o (`predicadoObrigatoriedade`): o candidato responde s\xf3\\n  quando a condi\xe7\xe3o vale.","A obrigatoriedade veio com outro valor, com `SEMPRE` ou `NUNCA` acompanhado de\\ncondi\xe7\xe3o, ou com `QUANDO` sem condi\xe7\xe3o. A recusa vem em\\n`itens[n].obrigatoriedade`, `grupos[n].obrigatoriedade` ou\\n`grupos[n].subitens[m].obrigatoriedade`, conforme o caso. Se a pr\xf3pria condi\xe7\xe3o\\nestiver mal formada, a recusa \xe9 da condi\xe7\xe3o (`predicadoObrigatoriedade`), e esta\\nn\xe3o aparece.","A confer\xeancia \xe9 de forma e vem antes de qualquer leitura do cat\xe1logo de fatos; as\\nrecusas de todos os itens e grupos se acumulam no array `errors[]`. Na aplica\xe7\xe3o de\\num modelo de formul\xe1rio (`POST .../formularios/aplicacoes-de-modelo`), os itens e\\nos grupos do modelo passam pela mesma confer\xeancia, e a recusa vem na posi\xe7\xe3o do\\nmodelo."],"comoResolver":["Na grava\xe7\xe3o, corrija a obrigatoriedade do campo indicado: use `SEMPRE` ou `NUNCA`\\nsem condi\xe7\xe3o, ou `QUANDO` com a condi\xe7\xe3o que diz em que caso o campo \xe9 obrigat\xf3rio.\\nNa aplica\xe7\xe3o do modelo, o conte\xfado do modelo est\xe1 inconsistente com a regra, e a\\ncorre\xe7\xe3o \xe9 feita no modelo por quem gere os modelos de formul\xe1rio; enquanto isso,\\nconfigure o formul\xe1rio diretamente no processo."],"ondeAparece":["Grava\xe7\xe3o dos itens do formul\xe1rio","Aplica\xe7\xe3o de modelo de formul\xe1rio"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Fato coletado"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);